<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Loja Virtual</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <header>
    <div class="container">
      <h1>🛍️ Loja Virtual</h1>
      <nav>
        <div id="menu-visitante">
          <button onclick="mostrarLogin()">Entrar</button>
          <button onclick="mostrarRegistro()">Criar Conta</button>
        </div>
        <div id="menu-usuario" style="display:none;">
          <span id="nome-usuario"></span>
          <button onclick="mostrarCarrinho()">🛒 Carrinho (<span id="qtd-carrinho">0</span>)</button>
          <button onclick="mostrarMeusPedidos()">Meus Pedidos</button>
          <button id="btn-admin" onclick="mostrarAdmin()" style="display:none;">⚙️ Administração</button>
          <button onclick="logout()">Sair</button>
        </div>
      </nav>
    </div>
  </header>

  <main class="container">
    <!-- Tela Inicial / Produtos -->
    <div id="tela-produtos" class="tela">
      <div class="filtros">
        <input type="text" id="busca" placeholder="Buscar produtos..." onkeyup="carregarProdutos()">
        <select id="filtro-categoria" onchange="carregarProdutos()">
          <option value="">Todas as categorias</option>
        </select>
      </div>
      <div id="lista-produtos" class="grid-produtos"></div>
    </div>

    <!-- Login -->
    <div id="tela-login" class="tela" style="display:none;">
