      <div class="form-container">
        <h2>Criar Conta</h2>
        <form onsubmit="fazerRegistro(event)">
          <input type="text" id="reg-nome" placeholder="Nome completo" required>
          <input type="email" id="reg-email" placeholder="Email" required>
          <input type="password" id="reg-senha" placeholder="Senha" required>
          <button type="submit">Cadastrar</button>
          <p><a href="#" onclick="mostrarLogin(); return false;">Já tem conta? Entre aqui</a></p>
        </form>
      </div>
    </div>

    <!-- Carrinho -->
    <div id="tela-carrinho" class="tela" style="display:none;">
      <h2>Meu Carrinho</h2>
      <div id="itens-carrinho"></div>
      <div id="carrinho-vazio" style="display:none;">
        <p>Seu carrinho está vazio</p>
        <button onclick="mostrarProdutos()">Continuar Comprando</button>
      </div>
      <div id="carrinho-com-itens" style="display:none;">
        <div class="total-carrinho">
          <h3>Total: R$ <span id="total-carrinho">0.00</span></h3>
        </div>
        <div class="form-container">
