          </form>
        </div>
        <div id="lista-admin-produtos"></div>
      </div>

      <!-- Aba Pedidos -->
      <div id="admin-pedidos" class="admin-aba" style="display:none;">
        <div id="lista-admin-pedidos"></div>
      </div>
    </div>

    <!-- Detalhes do Pedido -->
    <div id="tela-detalhes-pedido" class="tela" style="display:none;">
      <button onclick="voltarParaPedidos()">← Voltar</button>
      <div id="detalhes-pedido"></div>
    </div>
  </main>

  <div id="mensagem" class="mensagem"></div>

  <script src="app.js"></script>
</body>
</html>

