<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Configurar Administrador</title>
  <link rel="stylesheet" href="styles.css">
</head>
<body>
  <div class="container">
    <div class="form-container" style="margin-top: 50px;">
      <h1>🔐 Configurar Primeiro Administrador</h1>
      <p>Esta página permite criar a primeira conta de administrador do sistema.</p>
      <div id="mensagem-setup"></div>
      <form onsubmit="criarAdmin(event)">
        <input type="text" id="admin-nome" placeholder="Nome completo" required>
        <input type="email" id="admin-email" placeholder="Email" required>
        <input type="password" id="admin-senha" placeholder="Senha" required>
        <button type="submit">Criar Administrador</button>
      </form>
      <p style="margin-top: 20px;">
        <a href="/">Ir para a loja</a>
      </p>
    </div>
  </div>

  <script>
    async function criarAdmin(event) {
      event.preventDefault();

      const dados = {
        nome: document.getElementById('admin-nome').value,
        email: document.getElementById('admin-email').value,
        senha: document.getElementById('admin-senha').value
      };

      try {
        const res = await fetch('/api/registro-admin', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(dados)
        });

        const resultado = await res.json();

        if (resultado.sucesso) {
          document.getElementById('mensagem-setup').innerHTML = 
            '<div class="sucesso">✅ Administrador criado com sucesso! <a href="/">Clique aqui para fazer login</a></div>';
          event.target.reset();
        } else {
          document.getElementById('mensagem-setup').innerHTML = 
            `<div class="erro">❌ ${resultado.erro}</div>`;
        }
      } catch (erro) {
        document.getElementById('mensagem-setup').innerHTML = 
          '<div class="erro">❌ Erro ao criar administrador</div>';
      }
    }
  </script>
